def add_majors(apps, schema_editor):
    Major = apps.get_model("main", "Major")

    for name in MAJORS:
        Major.objects.get_or_create(major_name=name)


def remove_majors(apps, schema_editor):
    Major = apps.get_model("main", "Major")
    Major.objects.filter(major_name__in=MAJORS).delete()


